import re
import time
import logging

from taf.ul.bts_components.invoke_shell.InvokeShellHandler import InvokeSshHandler
from taf.hw.rf_diagnostic_card.exceptions import FHNETConnectionError, RmodConnectionError, DownloadFileError

from taf.rfrl.csv4all.resources.node.ru_manager.ru_configuration import RuConfiguration
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger
logger = logging.getLogger(__name__)

class RmodSshSession(InvokeSshHandler):
    def __init__(self, ssh_manager, smod_ip, username, password):
        super().__init__(smod_ip, username, password)
        self.proxy = None
        self.ssh_manager = ssh_manager
        self.logger = logger
        self.connection = None
        self._master_bts_alias = self._get_master_bts_alias()
        self.serial_number_path = "/mnt/factory/configs/unit/module_serial_number.txt"
        self.downloaded_file_path = "/ram/"


    def add_flags_on_rmod(self, rmod_instance: RuConfiguration):
        self.rmod_connection(rmod_instance, self._add_flags)

    def restore_flags_on_rmod(self, rmod_instance: RuConfiguration):
        self.rmod_connection(rmod_instance, self._restore_flags)

    def download_blackbox_from_rmod(self, rmod_instance: RuConfiguration, target_dir: str):
        self.rmod_connection(rmod_instance, self._download_blackbox)
        target_file = self.ssh_manager.get_file_from_bts(bts_file_path=f"{self.downloaded_file_path}/BBOX5",
                                           target_dir=target_dir,
                                           file_name=f"{rmod_instance.serial_number}_BBOX5",
                                           slave_smod=rmod_instance.slave_bts)
        rmod_instance.blackbox.set_blackbox_file(target_file)

    def execute_command_on_rmods(self, rmod_instance: RuConfiguration):
        self.rmod_connection(rmod_instance, self._execute_commands_on_rmods)

    def _execute_commands_on_rmods(self, rmod_instance: RuConfiguration):
        for command in rmod_instance.commands_after_connect:
            test_logger(f"[{rmod_instance.serial_number}] Executing command: {command}")
            output = self.send_command_and_return_output(command)
            test_logger(f"output: {output}", "DEBUG")

    def rmod_connection(self, rmod_instance: RuConfiguration, method, *args, **kwargs):
        radio_name = rmod_instance.radio_type
        if radio_name.startswith("F"):
            test_logger(f"[{radio_name}] Radio Modules with telnet interface are not supported", "WARN")
            return
        smod = self.ssh_manager.slave_smod if rmod_instance.slave_bts else self.ssh_manager.master_smod
        with smod as ssh_manager:
            self._session = ssh_manager.connection
            test_logger("Reconnecting channel session...", "DEBUG")
            self.reconnect_channel_session()
            test_logger(f"Connecting to {rmod_instance.ip_address}", "DEBUG")
            try:
                self.connect_to_rmod(rmod_instance.ip_address, rmod_instance.username, rmod_instance.password,
                                     slave_bts=rmod_instance.slave_bts)
                method(rmod_instance, *args, **kwargs)
            except RmodConnectionError as e:
                test_logger(e, "ERROR")

    def _add_flags(self, rmod_instance: RuConfiguration):
        if rmod_instance.restore_flags:
            self._restore_flags(rmod_instance)
        for flag, value in rmod_instance.flags_to_add.items():
            output = self.send_command_and_return_output(f"ccsShell.sh rad -mpw {flag} {value}")
            if "written succesfully" in output:
                test_logger(f"[{rmod_instance.serial_number}] Flag {flag}={value} added successfully")
            else:
                test_logger(f"[{rmod_instance.serial_number}] Flag: {flag}={value} couldn't be added!", "ERROR")
        if rmod_instance.preserve_flags:
            test_logger(f"[{rmod_instance.serial_number}] Executing command: touch /ram/disable_swman_cleanup")
            self._create_file_preserving_rmod_flags()
        if rmod_instance.commands_after_connect:
            self._execute_commands_on_rmods(rmod_instance)

    def _restore_flags(self, rmod_instance: RuConfiguration):
        test_logger("Restoring flags via command: ccsShell.sh mpf", "DEBUG")
        output = self.send_command_and_return_output(f"ccsShell.sh rad -mpf")
        if "Successfully" in output:
            test_logger(f"[{rmod_instance.serial_number}] Successfully restored flags")
        else:
            test_logger(f"[{rmod_instance.serial_number}]  Restoring flag has failed!", "ERROR")

    def connect_to_fhnet(self, container=None, timeout: int = 5, slave_bts: bool = False):
        """
        Connect to FHNET container through invoke shell terminal
        :param container: FHNET container address to which to connect (0x1018 or 0x2018).
                          Default value is None which means lxc-ls command output will be checked
        :type container: str
        :param timeout: Allowed time in seconds to establish connection. Default is 5s
        :type timeout: int
        :param slave_bts: Used for fullrack configuration only. True if connection should be performed to slave bts,
                          False in case of master bts connection or configurations other than fullrack.
                          Defaults to False.
        :type slave_bts: bool
        :return: True when connected to FHNET
        :rtype: bool
        :raises FHNETConnectionError exception when connection not established
        """
        test_logger("Connecting to FHNET", "DEBUG")
        smod_header = f"root@{self.slave_bts_alias}:" if slave_bts else f"root@{self.master_bts_alias}:"

        if not container:
            container = self._get_fhnet_container()
        cmd_to_fhnet = f"lxc-attach --name {container}"
        lxc_attach = self._send_command_and_return_output(command=cmd_to_fhnet, timeout=timeout)
        if "root@FHNET" in lxc_attach:
            self._verify_bts_side_for_connected_container(smod_header)
            test_logger("Successfully connected to FHNET", "DEBUG")
            return True

        raise FHNETConnectionError(f"Could NOT connect to FHNET \n {lxc_attach}")

    def _create_file_preserving_rmod_flags(self):
        """Creates /ram/disable_swman_cleanup file that will preserve RMOD flags i.e. after software update.
        Returns:
            None: Touch command does not return any output when succeeds.
        """
        self._send_command_and_return_output("touch /ram/disable_swman_cleanup")

    def _download_blackbox(self, rmod_instance: RuConfiguration):
        self.get_file_from_rmod_to_smod(filename="BBOX5", smod_path=self.downloaded_file_path,
                                                          rmod_path="/mnt/runtime/",
                                                          rmod_ip=rmod_instance.ip_address,
                                                          username=rmod_instance.username,
                                                          password=rmod_instance.password,
                                                          slave_bts=rmod_instance.slave_bts)

    def _download_file_from_rmod_to_fhnet(self, rmod_ip, username, password, filename, smod_path='/ram',
                                          rmod_path='/ram', timeout=300, slave_bts=False, switch_to_rfsw=False):

        self._logout_from_rmod()

        scp_command = f"scp -O {username}@{rmod_ip}:{rmod_path}/{filename} {smod_path}/{filename}"
        self.channel.send(scp_command + "\r")
        buff_shell_stdout = ""

        while timeout > 0:
            timeout -= 1
            time.sleep(1)
            shell_stdout = self._recv_data()
            buff_shell_stdout += shell_stdout
            if "(yes/no/[fingerprint])?" in shell_stdout:
                self.channel.send("yes" + "\r")
            elif shell_stdout.lower().endswith("password: "):
                self.channel.send(password + "\r")
            elif "100%" in shell_stdout:
                self.logger.info(f"Successfully downloaded file from RMOD IP:{rmod_ip} to FHNET")
                return f"{smod_path}/{filename}"
            elif "No such file or directory" in shell_stdout:
                raise DownloadFileError(
                    f"No such file or directory after scp: {scp_command} \n {buff_shell_stdout}"
                )

        raise DownloadFileError(
            f"Couldn't download file from RMOD IP:{rmod_ip} to FHNET, output from terminal \n {buff_shell_stdout}"
        )

    def _check_if_login_succeeded(self, rmod_ip):
        """
        Checks whether login to the RMOD was successful
        :param rmod_ip: RMOD ip address
        :type rmod_ip: str
        :return: True if login to RMOD succeeded otherwise False
        :rtype: str
        """
        shell_stdout = self._send_command_and_return_output(f"/sbin/ip a | grep {rmod_ip}", timeout=4,
                                                            repetition_interval=3)

        if "/sbin/ip: No such file or directory" in shell_stdout:
            shell_stdout = self._send_command_and_return_output(f"cat /proc/net/fib_trie | grep {rmod_ip}",
                                                                timeout=4, repetition_interval=3)
            if f"|-- {rmod_ip}" in shell_stdout:
                test_logger(f'Connected to RMOD {rmod_ip}', "DEBUG")
                return True
            return False

        try:
            cleaned_shell_stdout = re.search("/sbin/ip a.*", shell_stdout).string
        except AttributeError:
            cleaned_shell_stdout = ""
            test_logger(f"Something went wrong with the pattern search from invoke stdout - {shell_stdout}", "ERROR")

        if rmod_ip in cleaned_shell_stdout.replace(f"/sbin/ip a | grep {rmod_ip}", ''):
            test_logger(f'Connected to RMOD {rmod_ip}', "DEBUG")
            return True

        return False

    def _switch_to_rfsw_from_serviceuser(self):
        """
        Additional RMOD's user switch from 'serviceuser' to 'rfsw', required after CB010663 feature implementation.
        """
        shell_stdout = self._send_command_and_return_output(command='sudo su rfsw', timeout=10)

        if "rfsw@" in shell_stdout:
            test_logger("Rmod user has switched to 'rfsw'", "DEBUG")
            return

        raise RmodConnectionError(f"Login to 'rfsw' user has failed, login command output: {shell_stdout}")
